package main

import (
	"github.com/openabstractions/abstractions/mcp-gateway/startprofile"
	"strconv"
)

// Proposed C59 presentation. Settings store a recipe; runtime composition
// retains its nil approval resolver until the owner receives the presentation.
var claudeStartupPage = oaGroup("claude-startup-settings", "Automatic receiving", "Configure Claude to receive queued questions when it is closed. Startup permissions are reviewed separately in OpenAbstractions.",
	oaRow("Startup settings", "Choose a model, working folder, runtime and estimated budget.", `<button id="claude-startup-edit" disabled>Configure startup…</button>`, "claude-startup-status"),
	`<form id="claude-startup-form" hidden>`,
	oaRow("Model", "", `<input id="claude-startup-model" aria-label="Model" required maxlength="64" autocomplete="off">`, ""),
	oaRow("Working folder", "Working folder used at startup.", `<button type="button" id="claude-startup-folder">Choose working folder…</button>`, "claude-startup-folder-status"),
	oaRow("Maximum runtime", "Seconds", `<input id="claude-startup-seconds" aria-label="Maximum runtime in seconds" type="number" required min="1" max="`+strconv.FormatUint(startprofile.MaxTimeoutMS/1000, 10)+`" step="1">`, ""),
	oaRow("Estimated cost limit", "USD", `<input id="claude-startup-cost" aria-label="Estimated cost limit in USD" type="number" required min="0.01" max="`+strconv.FormatUint(startprofile.MaxBudgetCents/100, 10)+`" step="0.01">`, ""),
	oaExpander("Advanced limits", oaRow("Captured output limit", "KiB", `<input id="claude-startup-output" aria-label="Captured output limit in KiB" type="number" min="1" max="`+strconv.FormatUint(startprofile.MaxOutputBytes/1024, 10)+`" step="1">`, "")+oaRow("Process memory limit", "MiB", `<input id="claude-startup-memory" aria-label="Process memory limit in MiB" type="number" min="1" max="`+strconv.FormatUint(startprofile.MaxMemoryBytes/(1024*1024), 10)+`" step="1">`, "")),
	oaRow("Changes", "", `<button type="submit" id="claude-startup-save">Save startup settings</button><button type="button" id="claude-startup-disable" disabled>Disable startup</button><button type="button" id="claude-startup-reconcile" disabled hidden>Finish saving</button><button type="button" id="claude-startup-cancel">Cancel</button>`, "claude-startup-save-status"), `</form>`)

const claudeStartupScript = `
let claudeStartupRevisionToken=0,claudeStartupRun=null,claudeStartupRevision='';
function closeClaudeStartup(){claudeStartupRevisionToken++;if(claudeStartupRun)claudeStartupRun.abort();claudeStartupRevision='';el('claude-startup-form').hidden=true;el('claude-startup-save').disabled=true;el('claude-startup-disable').disabled=true;el('claude-startup-reconcile').disabled=true}
function drawClaudeStartupAvailability(view){closeClaudeStartup();el('claude-startup-edit').disabled=!(view.connections||[]).some(row=>row.kind==='user'&&row.registration==='saved');el('claude-startup-status').textContent='Startup settings are saved separately from startup permissions.'}
function claudeStartupOperation(){const revision=++claudeStartupRevisionToken;if(claudeStartupRun)claudeStartupRun.abort();const run=new AbortController();claudeStartupRun=run;return {revision,run}}
function claudeStartupCurrent(op){return !claudeClosed&&!op.run.signal.aborted&&op.revision===claudeStartupRevisionToken}
async function editClaudeStartup(){if(claudeClosed)return;const op=claudeStartupOperation();el('claude-startup-status').textContent='Reading saved startup settings…';try{const view=await call('/connections/claude/startup/state',{revision:claudeViewRevision},op.run.signal);if(!claudeStartupCurrent(op))return;if(view.outcome!=='page')throw new Error('Startup settings unavailable');claudeStartupRevision=view.revision;for(const [id,value] of [['model',view.model],['seconds',view.timeout_ms?view.timeout_ms/1000:''],['cost',view.budget_cents?view.budget_cents/100:''],['output',view.output_bytes?view.output_bytes/1024:''],['memory',view.memory_bytes?view.memory_bytes/(1024*1024):'']])el('claude-startup-'+id).value=value||'';el('claude-startup-folder-status').textContent=view.folder||'No working folder selected.';el('claude-startup-save-status').textContent='';el('claude-startup-form').hidden=false;el('claude-startup-save').disabled=!!view.recovery;el('claude-startup-disable').disabled=!view.configured||!!view.recovery;el('claude-startup-reconcile').disabled=!view.recovery;el('claude-startup-reconcile').hidden=!view.recovery;el('claude-startup-save').hidden=!!view.recovery;el('claude-startup-disable').hidden=!!view.recovery;el('claude-startup-reconcile').textContent='Finish saving';for(const id of ['model','seconds','cost','output','memory','folder'])el('claude-startup-'+id).disabled=!!view.recovery;el('claude-startup-status').textContent=view.recovery?'The Claude connection is unavailable. Finish saving can complete an interrupted save.':'Edit startup settings.';}catch(error){if(claudeStartupCurrent(op))fail('claude-startup-status',error)}}
async function chooseClaudeStartupFolder(){if(!claudeStartupRevision||claudeClosed)return;const op=claudeStartupOperation();try{const view=await call('/connections/claude/startup/folder',{revision:claudeStartupRevision},op.run.signal);if(claudeStartupCurrent(op)&&view.folder){el('claude-startup-folder-status').textContent=view.folder;}}catch(error){if(claudeStartupCurrent(op))fail('claude-startup-folder-status',error)}}
async function saveClaudeStartup(action){if(!claudeStartupRevision||claudeClosed)return;const op=claudeStartupOperation(),body={revision:claudeStartupRevision};if(action==='configure'){const integer=id=>{const raw=el('claude-startup-'+id).value;const n=Number(raw);if(!raw||!Number.isSafeInteger(n)||n<=0)throw new Error('Select every model, folder and limit before saving.');return n};try{body.model=el('claude-startup-model').value;body.timeout_ms=integer('seconds')*1000;const cost=el('claude-startup-cost').value;if(!/^\d+(\.\d{1,2})?$/.test(cost))throw new Error('Select an estimated budget in USD.');const parts=cost.split('.');body.budget_cents=Number(parts[0])*100+Number((parts[1]||'').padEnd(2,'0'));if(!Number.isSafeInteger(body.budget_cents)||body.budget_cents<=0)throw new Error('Select a positive estimated budget.');body.output_bytes=el('claude-startup-output').value?integer('output')*1024:0;body.memory_bytes=el('claude-startup-memory').value?integer('memory')*1024*1024:0;if(!body.model)throw new Error('Select a model before saving.')}catch(error){fail('claude-startup-save-status',error);return}}
el('claude-startup-save').disabled=true;el('claude-startup-disable').disabled=true;el('claude-startup-reconcile').disabled=true;el('claude-startup-save-status').textContent='Saving startup settings…';try{await call('/connections/claude/startup/'+action,body,op.run.signal);if(!claudeStartupCurrent(op))return;closeClaudeStartup();el('claude-startup-status').textContent=action==='disable'?'Startup settings removed. Your Claude connection remains saved.':action==='finish'?'Interrupted save finished. Open settings to review the outcome.':'Startup settings saved.';}catch(error){if(claudeStartupCurrent(op)){el('claude-startup-save-status').textContent=String(error)+' Open startup settings to inspect or finish any interrupted settings.';claudeStartupRevision='';}}}
el('claude-startup-edit').onclick=editClaudeStartup;el('claude-startup-folder').onclick=chooseClaudeStartupFolder;el('claude-startup-form').onsubmit=event=>{event.preventDefault();return saveClaudeStartup('configure')};el('claude-startup-disable').onclick=()=>saveClaudeStartup('disable');el('claude-startup-reconcile').onclick=()=>saveClaudeStartup('finish');el('claude-startup-cancel').onclick=closeClaudeStartup;addEventListener('pagehide',closeClaudeStartup,{once:true});
`
